fn equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both inputs have the same length
    assert_eq!(a.len(), b.len());
    // Zip the two vectors together, compare each pair, and collect into a Vec<bool>
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x == y)
     .collect()
}

